mapper.select:
SELECT id, organization, alias, org_owner, tenant_id, parentId, org_rank, createDate, remarks, parentKeys, org_category, enabled, org_type, order_no FROM LA_ORGANIZATION O
AND O.org_owner = #{parameters.owner}
AND O.org_owner IS NULL
AND O.organization LIKE #{parameters.name}
AND O.alias LIKE #{parameters.alias}
AND O.id IN
#{item}
ORDER BY O.org_rank, O.order_no, O.parentId, O.organization

SELECT id, alias AS name, parentId AS pid FROM LA_ORGANIZATION O WHERE O.enabled = 1
AND O.org_owner = #{parameters.owner}
AND O.org_owner IS NULL
AND O.parentKeys LIKE #{parameters.parentKeys}
ORDER BY O.org_rank, O.order_no, O.parentId, O.organization

SELECT id, organization, alias, parentId, org_rank, createDate, remarks, parentKeys FROM LA_ORGANIZATION O
AND id != #{organization.id}
AND organization = #{organization.name}
AND tenant_id = #{organization.tenant_id}
AND tenant_id IS NULL
ORDER BY createdate

mapper.update:
UPDATE LA_USERS T SET T.enabled = #{enabled} WHERE T.username IN (
    SELECT T2.USERID FROM la_user_organization T2
    INNER JOIN la_organization T3 ON T2.ORGANIZATIONID = T3.ID
    WHERE T3.ID IN
    #{item}
)

UPDATE LA_ORGANIZATION T SET
T.org_rank = CASE

    WHEN id = #{item.id} THEN #{item.level}

END,
parentid = CASE

    WHEN id = #{item.id} THEN #{item.parentId}

END,
parentKeys = CASE

    WHEN id = #{item.id} THEN #{item.parentKeys}

END,
order_no = CASE

    WHEN id = #{item.id} THEN #{item.orderNo}

END
WHERE id IN

    #{item.id}
